//! Controls of the conformance suite itself.
//!
//! * Positive controls: reference algorithms with vectors generated by an
//!   independent implementation (Python) must pass with zero failures.
//! * Negative controls: each deliberately defective algorithm must fail in
//!   the group that targets that defect. A suite that cannot fail proves
//!   nothing; `Tools/mutation_conformance.py` then attacks the suite itself.

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use hmac::{Hmac, Mac};
use lacre_core::suite::{CostClass, OutputKind, SealInput, SealMac, Status};
use lacre_seal_conformance::{
    check_catalogue, check_crossed, check_seal_mac, Group, Kat, Options, Report, SlowMac,
};
use sha2::{Sha256, Sha512};

// ------------------------------------------------------------ references

fn h256(key: &[u8], parts: &[&[u8]], out: &mut [u8]) {
    let mut m = Hmac::<Sha256>::new_from_slice(key).unwrap();
    for p in parts {
        m.update(p);
    }
    out.copy_from_slice(&m.finalize().into_bytes());
}

fn h512(key: &[u8], parts: &[&[u8]], out: &mut [u8]) {
    let mut m = Hmac::<Sha512>::new_from_slice(key).unwrap();
    for p in parts {
        m.update(p);
    }
    out.copy_from_slice(&m.finalize().into_bytes());
}

fn xof(key: &[u8], parts: &[&[u8]], out: &mut [u8]) {
    let key: [u8; 32] = key.try_into().unwrap();
    let mut h = blake3::Hasher::new_keyed(&key);
    for p in parts {
        h.update(p);
    }
    h.finalize_xof().fill(out);
}

type Body = dyn Fn(&[u8], &SealInput<'_>, &mut [u8]) + Send + Sync;

/// A configurable algorithm: metadata plus an arbitrary body.
struct Ctl {
    id: &'static str,
    key_len: usize,
    output: OutputKind,
    cost: CostClass,
    bits: u16,
    body: Box<Body>,
}

impl SealMac for Ctl {
    fn id(&self) -> &'static str {
        self.id
    }
    fn status(&self) -> Status {
        Status::Experimental
    }
    fn cost(&self) -> CostClass {
        self.cost
    }
    fn security_bits(&self) -> u16 {
        self.bits
    }
    fn key_len(&self) -> usize {
        self.key_len
    }
    fn output(&self) -> OutputKind {
        self.output
    }
    fn mac(&self, key: &[u8], input: &SealInput<'_>, out: &mut [u8]) {
        (self.body)(key, input, out)
    }
}

const XOF: OutputKind = OutputKind::Xof { min: 16, max: 1024 };

/// An extendable-output control (reference: keyed BLAKE3) with a custom body.
fn xof_ctl(id: &'static str, body: impl Fn(&[u8], &SealInput<'_>, &mut [u8]) + Send + Sync + 'static) -> Arc<dyn SealMac> {
    Arc::new(Ctl { id, key_len: 32, output: XOF, cost: CostClass::Light, bits: 128, body: Box::new(body) })
}

/// The correct extendable-output algorithm.
fn good_xof(id: &'static str) -> Arc<dyn SealMac> {
    xof_ctl(id, |k, i, o| xof(k, &i.parts(), o))
}

fn good_h256() -> Arc<dyn SealMac> {
    Arc::new(Ctl {
        id: "hmac-sha256",
        key_len: 32,
        output: OutputKind::Fixed(32),
        cost: CostClass::Light,
        bits: 128,
        body: Box::new(|k, i, o| h256(k, &i.parts(), o)),
    })
}

fn good_h512() -> Arc<dyn SealMac> {
    Arc::new(Ctl {
        id: "hmac-sha512",
        key_len: 64,
        output: OutputKind::Fixed(64),
        cost: CostClass::Standard,
        bits: 256,
        body: Box::new(|k, i, o| h512(k, &i.parts(), o)),
    })
}

// ------------------------------------------------------- independent KATs

fn kats_for(seal_id: &str) -> Vec<Kat> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../spec/vectors/suite-v2.json");
    let v: serde_json::Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let mut out = Vec::new();
    for case in v["cases"].as_array().unwrap() {
        if case["seal_id"] != seal_id {
            continue;
        }
        for (i, f) in case["frames"].as_array().unwrap().iter().enumerate() {
            out.push(
                Kat::from_hex(
                    &format!("{} / frame {i}", case["name"].as_str().unwrap()),
                    case["seal_key_hex"].as_str().unwrap(),
                    f["fragment_hex"].as_str().unwrap(),
                    f["state_hex"].as_str().unwrap(),
                    f["tag_hex"].as_str().unwrap(),
                )
                .unwrap(),
            );
        }
    }
    assert!(!out.is_empty(), "no vectors for {seal_id}");
    out
}

fn opts() -> Options {
    Options::default()
}

fn run(mac: Arc<dyn SealMac>, kats: &[Kat]) -> Report {
    check_seal_mac(mac, kats, &opts())
}

/// The negative control must fail in every group listed in `must`.
fn expect_fail(name: &str, rep: &Report, must: &[Group]) {
    let failed = rep.failed_groups();
    for g in must {
        assert!(
            failed.contains(g),
            "control '{name}' should fail group {g:?}, failed groups: {failed:?}\n{}",
            rep.summary()
        );
    }
}

/// Same, but ignoring the vectors group: proves the defect is also caught by
/// behavioural checks, independently of any vector the author supplied.
fn expect_fail_without_vectors(name: &str, rep: &Report, must: &[Group]) {
    let failed: Vec<Group> = rep.failed_groups().into_iter().filter(|g| *g != Group::Vectors).collect();
    for g in must {
        assert!(failed.contains(g), "control '{name}': group {g:?} not caught independently of vectors: {failed:?}\n{}", rep.summary());
    }
}

// ------------------------------------------------------ positive controls

#[test]
fn positive_hmac_sha256_passes() {
    run(good_h256(), &kats_for("hmac-sha256")).assert_passed();
}

#[test]
fn positive_hmac_sha512_passes() {
    run(good_h512(), &kats_for("hmac-sha512")).assert_passed();
}

#[test]
fn positive_blake3_xof_passes_with_independent_vectors() {
    let r = run(good_xof("blake3-keyed-xof"), &kats_for("blake3-keyed-xof"));
    r.assert_passed();
    // The run is substantial, not a handful of trivial checks.
    assert!(r.total() >= 35, "only {} checks ran", r.total());
}

#[test]
fn positive_catalogue_of_three_passes() {
    let entries = vec![
        (good_h256(), kats_for("hmac-sha256")),
        (good_h512(), kats_for("hmac-sha512")),
        (good_xof("blake3-keyed-xof"), kats_for("blake3-keyed-xof")),
    ];
    check_catalogue(&entries, &opts()).assert_passed();
}

#[test]
fn an_empty_report_is_not_a_pass() {
    assert!(!Report::default().passed());
}

// ------------------------------------------------------ negative controls

fn xk() -> Vec<Kat> {
    kats_for("blake3-keyed-xof")
}

#[test]
fn negative_constant_tag() {
    let m = xof_ctl("blake3-keyed-xof", |_, _, o| o.fill(0xAB));
    let r = run(m, &xk());
    expect_fail("constant tag", &r, &[Group::Lengths, Group::Sensitivity, Group::Vectors]);
    expect_fail_without_vectors("constant tag", &r, &[Group::Sensitivity]);
}

#[test]
fn negative_ignores_key() {
    let m = xof_ctl("blake3-keyed-xof", |_, i, o| xof(&[7u8; 32], &i.parts(), o));
    expect_fail_without_vectors("ignores key", &run(m, &xk()), &[Group::Sensitivity]);
}

#[test]
fn negative_ignores_chain_state() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        xof(k, &[p[0], p[1]], o)
    });
    expect_fail_without_vectors("ignores state", &run(m, &xk()), &[Group::Sensitivity]);
}

#[test]
fn negative_ignores_last_fragment_byte() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        let f = p[1];
        let cut = if f.is_empty() { f } else { &f[..f.len() - 1] };
        xof(k, &[p[0], cut, p[2]], o)
    });
    expect_fail_without_vectors("ignores last byte", &run(m, &xk()), &[Group::Sensitivity]);
}

#[test]
fn negative_ignores_a_middle_byte_of_large_fragments() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        let mut f = p[1].to_vec();
        if f.len() > 511 {
            f[511] = 0;
        }
        xof(k, &[p[0], &f, p[2]], o)
    });
    expect_fail_without_vectors("ignores middle byte", &run(m, &xk()), &[Group::Sensitivity]);
}

#[test]
fn negative_tail_does_not_depend_on_input() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        xof(k, &i.parts(), o);
        let n = o.len();
        if n >= 16 {
            let mut t = [0u8; 8];
            xof(k, &[b"fixed"], &mut t);
            o[n - 8..].copy_from_slice(&t);
        }
    });
    expect_fail_without_vectors("tail independent", &run(m, &xk()), &[Group::Sensitivity]);
}

#[test]
fn negative_writes_fewer_bytes_than_declared() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let n = o.len();
        xof(k, &i.parts(), &mut o[..n - 1]);
    });
    expect_fail_without_vectors("short write", &run(m, &xk()), &[Group::Lengths]);
}

#[test]
fn negative_nondeterministic() {
    let c = Arc::new(AtomicUsize::new(0));
    let m = xof_ctl("blake3-keyed-xof", move |k, i, o| {
        xof(k, &i.parts(), o);
        o[0] ^= (c.fetch_add(1, Ordering::SeqCst) & 1) as u8;
    });
    expect_fail_without_vectors("nondeterministic", &run(m, &xk()), &[Group::Lengths, Group::Journey]);
}

#[test]
fn negative_panics_on_empty_fragment() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        if i.parts()[1].is_empty() {
            panic!("boom on empty");
        }
        xof(k, &i.parts(), o);
    });
    let r = run(m, &xk());
    expect_fail_without_vectors("panic", &r, &[Group::Lengths]);
    assert!(r.failures().iter().any(|c| c.failure.as_deref().unwrap().contains("panicked")));
}

#[test]
fn negative_depends_on_previous_call() {
    let last = Arc::new(Mutex::new(usize::MAX));
    let m = xof_ctl("blake3-keyed-xof", move |k, i, o| {
        xof(k, &i.parts(), o);
        let mut l = last.lock().unwrap();
        if *l == 10 {
            o[0] ^= 1;
        }
        *l = i.parts()[1].len();
    });
    expect_fail_without_vectors("stateful", &run(m, &xk()), &[Group::Statelessness]);
}

#[test]
fn negative_result_depends_on_the_calling_thread() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        xof(k, &i.parts(), o);
        if std::thread::current().name().is_none() {
            o[0] ^= 1;
        }
    });
    expect_fail_without_vectors("thread dependent", &run(m, &xk()), &[Group::Statelessness]);
}

#[test]
fn negative_silent_truncation_with_periodic_fill() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let mut full = [0u8; 32];
        xof(k, &i.parts(), &mut full);
        for (j, b) in o.iter_mut().enumerate() {
            *b = full[j % 32];
        }
    });
    expect_fail_without_vectors("periodic fill", &run(m, &xk()), &[Group::Lengths]);
}

#[test]
fn negative_zero_padded_output() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        o.fill(0);
        let n = o.len().min(32);
        xof(k, &i.parts(), &mut o[..n]);
    });
    expect_fail_without_vectors("zero padded", &run(m, &xk()), &[Group::Lengths]);
}

#[test]
fn negative_ignores_last_key_byte() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let mut k2 = k.to_vec();
        k2[31] = 0;
        xof(&k2, &i.parts(), o);
    });
    expect_fail_without_vectors("weak key", &run(m, &xk()), &[Group::Sensitivity]);
}

#[test]
fn negative_declares_64_byte_key_but_uses_32() {
    let m: Arc<dyn SealMac> = Arc::new(Ctl {
        id: "blake3-keyed-xof",
        key_len: 64,
        output: XOF,
        cost: CostClass::Light,
        bits: 128,
        body: Box::new(|k, i, o| xof(&k[..32], &i.parts(), o)),
    });
    // The author's vectors are 32-byte-key vectors: the key-length mismatch
    // is caught by the vectors group, and the unused half by sensitivity.
    let r = run(m, &xk());
    expect_fail("unused key half", &r, &[Group::Vectors]);
    expect_fail_without_vectors("unused key half", &r, &[Group::Sensitivity]);
}

#[test]
fn negative_length_prefix_dropped_only_vectors_can_tell() {
    // With a fixed 32-byte Es(i), `f ∥ Es` is already injective, so dropping
    // the length prefix creates no collision that a behavioural check could
    // observe (a first attempt at such a check was vacuous and was removed).
    // Only a vector computed over the canonical message detects it.
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        xof(k, &[p[1], p[2]], o);
    });
    let r = run(m, &xk());
    assert_eq!(r.failed_groups(), vec![Group::Vectors], "{}", r.summary());
}

#[test]
fn negative_parts_in_the_wrong_order_only_vectors_can_tell() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        xof(k, &[p[2], p[1], p[0]], o);
    });
    let r = run(m, &xk());
    expect_fail("wrong order", &r, &[Group::Vectors]);
    // Every behavioural group is blind to a consistent re-ordering: this
    // control documents why vectors are mandatory.
    assert_eq!(r.failed_groups(), vec![Group::Vectors], "{}", r.summary());
}

#[test]
fn negative_correct_algorithm_with_a_wrong_vector() {
    let mut k = xk();
    let last = k[0].expected.len() - 1;
    k[0].expected[last] ^= 1;
    let r = run(good_xof("blake3-keyed-xof"), &k);
    assert_eq!(r.failed_groups(), vec![Group::Vectors], "{}", r.summary());
}

#[test]
fn negative_no_vectors_is_not_a_pass() {
    let r = run(good_xof("blake3-keyed-xof"), &[]);
    assert!(!r.passed());
    assert_eq!(r.failed_groups(), vec![Group::Vectors]);
}

#[test]
fn negative_vector_with_wrong_key_length_or_tag_length() {
    let mut k = xk();
    k[0].key.pop();
    expect_fail("short vector key", &run(good_xof("blake3-keyed-xof"), &k), &[Group::Vectors]);
    let mut k = xk();
    k[0].expected.truncate(8); // below the declared minimum of 16
    expect_fail("short vector tag", &run(good_xof("blake3-keyed-xof"), &k), &[Group::Vectors]);
}

#[test]
fn negative_metadata_liars() {
    let kats = xk();
    let mk = |id: &'static str, key_len, output, bits| -> Arc<dyn SealMac> {
        Arc::new(Ctl { id, key_len, output, cost: CostClass::Light, bits, body: Box::new(|k, i, o| xof(&k[..32.min(k.len())], &i.parts(), o)) })
    };
    for (name, m) in [
        ("key_len 8", mk("blake3-keyed-xof", 8, XOF, 128)),
        ("key_len 4096", mk("blake3-keyed-xof", 4096, XOF, 128)),
        ("xof max 2000", mk("blake3-keyed-xof", 32, OutputKind::Xof { min: 16, max: 2000 }, 128)),
        ("xof min 0", mk("blake3-keyed-xof", 32, OutputKind::Xof { min: 0, max: 32 }, 128)),
        ("xof min > max", mk("blake3-keyed-xof", 32, OutputKind::Xof { min: 64, max: 32 }, 128)),
        ("fixed 0", mk("blake3-keyed-xof", 32, OutputKind::Fixed(0), 128)),
        ("fixed 2048", mk("blake3-keyed-xof", 32, OutputKind::Fixed(2048), 128)),
        ("uppercase id", mk("Blake3", 32, XOF, 128)),
        ("empty id", mk("", 32, XOF, 128)),
        ("security_bits 0", mk("blake3-keyed-xof", 32, XOF, 0)),
    ] {
        let r = run(m, &kats);
        expect_fail(name, &r, &[Group::Metadata]);
    }
}

#[test]
fn parameters_check_is_present_for_fixed_algorithms() {
    // A Fixed(32) algorithm: the Core must reject params for it. This is
    // verified through the declaration; the control confirms the check runs
    // and passes for a correct Fixed algorithm (see positive controls) and
    // that its failure is reported under `Parameters`.
    let r = run(good_h256(), &kats_for("hmac-sha256"));
    assert!(r.checks().iter().any(|c| c.group == Group::Parameters && c.name.contains("rejects parameters")));
}

#[test]
fn negative_alias_of_another_algorithm_under_a_new_id() {
    let a = good_xof("blake3-keyed-xof");
    let alias = good_xof("blake3-keyed-xof-copy");
    let r = check_crossed(a.clone(), alias.clone());
    expect_fail("alias", &r, &[Group::Crossed]);
    let entries = vec![(a.clone(), xk()), (alias, xk())];
    expect_fail("alias in catalogue", &check_catalogue(&entries, &opts()), &[Group::Crossed]);
    // Different functions pass.
    check_crossed(good_h256(), a).assert_passed();
}

#[test]
fn negative_fixed_algorithm_that_equals_an_xof_at_one_length() {
    // Fixed(32) computed as the 32-byte output of the same keyed XOF: a
    // different id, but the same function wherever the ranges overlap (32 is
    // not among the XOF's own sampled lengths 16, 17, 520, 1024).
    let fixed: Arc<dyn SealMac> = Arc::new(Ctl {
        id: "xof-at-32",
        key_len: 32,
        output: OutputKind::Fixed(32),
        cost: CostClass::Light,
        bits: 128,
        body: Box::new(|k, i, o| xof(k, &i.parts(), o)),
    });
    let r = check_crossed(fixed, good_xof("blake3-keyed-xof"));
    expect_fail("overlap alias", &r, &[Group::Crossed]);
    assert!(failed_check(&r, "not the same function"), "{}", r.summary());
}

#[test]
fn negative_duplicate_ids_in_a_catalogue() {
    let entries = vec![(good_xof("blake3-keyed-xof"), xk()), (good_xof("blake3-keyed-xof"), xk())];
    let r = check_catalogue(&entries, &opts());
    expect_fail("duplicate ids", &r, &[Group::Crossed]);
    let named = |n: &str| r.failures().iter().any(|c| c.name.contains(n));
    assert!(named("ids are unique"), "{}", r.summary());
    assert!(named("ids differ"), "{}", r.summary());
}

#[test]
fn negative_declared_light_but_slow() {
    // 3 ms per call against a 1 ms budget for the Light class.
    let slow: Arc<dyn SealMac> = Arc::new(SlowMac { inner: good_xof("blake3-keyed-xof"), delay: Duration::from_millis(3) });
    let o = Options { light_budget: Duration::from_millis(1), slow_delay: Duration::from_millis(5), ..Options::default() };
    let r = check_seal_mac(slow, &xk(), &o);
    expect_fail("slow", &r, &[Group::Cost]);
    assert_eq!(r.failed_groups(), vec![Group::Cost], "{}", r.summary());
}

#[test]
fn a_slow_but_honest_algorithm_passes_when_declared_heavy() {
    let inner: Arc<dyn SealMac> = Arc::new(Ctl {
        id: "blake3-keyed-xof",
        key_len: 32,
        output: XOF,
        cost: CostClass::Heavy,
        bits: 128,
        body: Box::new(|k, i, o| xof(k, &i.parts(), o)),
    });
    let slow: Arc<dyn SealMac> = Arc::new(SlowMac { inner, delay: Duration::from_millis(2) });
    let o = Options { slow_delay: Duration::from_millis(5), ..Options::default() };
    check_seal_mac(slow, &xk(), &o).assert_passed();
}

// ------------------------------------------------------------ the journey

#[test]
fn negative_truncates_input_at_1024_bytes() {
    // Drops the length prefix and stops reading the fragment at 1024 bytes:
    // an extended or altered tail goes unnoticed. Behaviour on fragments of
    // up to 1 KiB is correct, so only large inputs reveal it.
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        let f = &p[1][..p[1].len().min(1024)];
        xof(k, &[f, p[2]], o);
    });
    let r = run(m, &xk());
    expect_fail_without_vectors("truncated input", &r, &[Group::Sensitivity]);
    // Also seen from the Core's side: an extended payload is accepted.
    expect_fail_without_vectors("truncated input (journey)", &r, &[Group::Journey]);
}

#[test]
fn negative_state_ignored_by_a_second_implementation_style() {
    // Tag independent of the fragment's *position in the session*: the
    // algorithm accepts anything with a matching static tag. The Core
    // recomputes, so a tamper test cannot pass unless the algorithm ignores
    // part of its input — which sensitivity also reports. Here the algorithm
    // ignores the state: replays of the same fragment in different positions
    // would verify; the journey group must still catch the tampering path.
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        xof(k, &[p[0], p[1]], o);
    });
    let r = run(m, &xk());
    expect_fail("state ignored", &r, &[Group::Sensitivity]);
}

#[test]
fn negative_degenerate_keys_collapse() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let uniform = k.iter().all(|&b| b == k[0]);
        let k2 = if uniform { vec![0u8; 32] } else { k.to_vec() };
        xof(&k2, &i.parts(), o);
    });
    expect_fail_without_vectors("degenerate keys", &run(m, &xk()), &[Group::Robustness]);
}

#[test]
fn negative_empty_fragment_aliases_a_zero_byte() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        if p[1].is_empty() {
            xof(k, &[&1u64.to_be_bytes(), &[0u8], p[2]], o);
        } else {
            xof(k, &p, o);
        }
    });
    expect_fail_without_vectors("empty == [0]", &run(m, &xk()), &[Group::Robustness]);
}

#[test]
fn negative_panics_on_huge_fragments() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        if i.parts()[1].len() > (1 << 19) {
            panic!("too big");
        }
        xof(k, &i.parts(), o);
    });
    expect_fail_without_vectors("huge panic", &run(m, &xk()), &[Group::Robustness]);
}

#[test]
fn negative_output_depends_on_timing() {
    // Flips a byte when more than 15 ms passed since the previous call: the
    // slowness group (20 ms per call) must see tags differ from the fast run.
    let last: Arc<Mutex<Option<std::time::Instant>>> = Arc::new(Mutex::new(None));
    let m = xof_ctl("blake3-keyed-xof", move |k, i, o| {
        xof(k, &i.parts(), o);
        let now = std::time::Instant::now();
        let mut l = last.lock().unwrap();
        if matches!(*l, Some(t) if now.duration_since(t) > Duration::from_millis(15)) {
            o[0] ^= 1;
        }
        *l = Some(now);
    });
    expect_fail_without_vectors("timing", &run(m, &xk()), &[Group::Slowness]);
}

/// The check with this name fragment failed.
fn failed_check(rep: &Report, name: &str) -> bool {
    rep.failures().iter().any(|c| c.name.contains(name))
}

#[test]
fn negative_nondeterministic_only_on_large_fragments() {
    let c = Arc::new(AtomicUsize::new(0));
    let m = xof_ctl("blake3-keyed-xof", move |k, i, o| {
        xof(k, &i.parts(), o);
        if i.parts()[1].len() >= 1024 {
            o[0] ^= (c.fetch_add(1, Ordering::SeqCst) & 1) as u8;
        }
    });
    let r = run(m, &xk());
    expect_fail_without_vectors("large nondeterminism", &r, &[Group::Lengths]);
    assert!(failed_check(&r, "block-boundary"), "{}", r.summary());
}

#[test]
fn negative_strips_trailing_zero_bytes() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        let mut end = p[1].len();
        while end > 0 && p[1][end - 1] == 0 {
            end -= 1;
        }
        xof(k, &[&p[1][..end], p[2]], o);
    });
    let r = run(m, &xk());
    expect_fail_without_vectors("trailing zeros", &r, &[Group::Lengths]);
    assert!(failed_check(&r, "distinct"), "{}", r.summary());
}

#[test]
fn negative_ignores_one_bit_of_the_fragment() {
    let m = xof_ctl("blake3-keyed-xof", |k, i, o| {
        let p = i.parts();
        let mut f = p[1].to_vec();
        if f.len() > 3 {
            f[3] &= 0xFE;
        }
        xof(k, &[p[0], &f, p[2]], o);
    });
    let r = run(m, &xk());
    assert!(failed_check(&r, "16-byte fragment"), "{}", r.summary());
}

#[test]
fn negative_randomly_nondeterministic_is_seen_by_the_session_check() {
    // Pseudo-random flip per call (LCG): sealing the same payload twice in
    // the same session must be noticed by the journey's determinism check.
    let st = Arc::new(Mutex::new(0x2545F491u64));
    let m = xof_ctl("blake3-keyed-xof", move |k, i, o| {
        xof(k, &i.parts(), o);
        let mut g = st.lock().unwrap();
        *g = g.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        if (*g >> 33) & 1 == 1 {
            o[0] ^= 1;
        }
    });
    let r = run(m, &xk());
    assert!(failed_check(&r, "deterministic per session"), "{}", r.summary());
}

// -------------------------------------------------- structural properties

#[test]
fn core_does_not_depend_on_the_conformance_crate() {
    let toml = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../lacre-core/Cargo.toml")).unwrap();
    assert!(!toml.contains("conformance"), "lacre-core must not depend on the conformance crate");
}

#[test]
fn the_suite_has_no_cryptographic_runtime_dependency() {
    let toml = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/Cargo.toml")).unwrap();
    let deps = toml.split("[dev-dependencies]").next().unwrap();
    for banned in ["hmac", "sha2", "sha3", "blake", "aes", "digest"] {
        assert!(!deps.contains(banned), "runtime dependency on '{banned}': the suite must not carry a hidden reference implementation");
    }
}

#[test]
fn the_suite_source_names_no_primitive() {
    for f in ["lib.rs", "checks.rs", "kat.rs", "report.rs"] {
        let src = std::fs::read_to_string(format!("{}/src/{f}", env!("CARGO_MANIFEST_DIR"))).unwrap();
        // Comments may mention primitives; code may not use them.
        for line in src.lines().filter(|l| !l.trim_start().starts_with("//")) {
            for banned in ["Hmac", "Sha256", "Sha512", "blake3::", "Hasher"] {
                assert!(!line.contains(banned), "{f}: code references {banned}: {line}");
            }
        }
    }
}
